import KwipMLCore
import Foundation

/// Shared authored content for the current data practices; reference and rail use one copy.
@MainActor enum DataPracticeLessonCopy {
    struct Packet {let introduction:String;let sections:[Section];let reflection:String}
    struct Section {let title:String;let text:String}
    static let packets:[String:Packet] = [
        "union":.init(introduction:"Monthly files often describe the same kind of record with different column orders. Union stacks those records into one table so later tools can process the months together.\n\nThe supplied canvas contains:\n- [January orders](kwip-node://data/source1): three records, including a repeated order number.\n- [February orders](kwip-node://data/source2): two records with fields in a different order.\n- [March orders](kwip-node://data/source3): two records without notes.\n- [All monthly orders](kwip-node://data/union): Union aligns the columns by name.\n- [Explore appended orders](kwip-node://data/view): View lets you inspect the combined table.\n\nNo model is trained here. Predict which fields will be missing and whether the repeated order should survive.",sections:[
            .init(title:"Predict and run",text:"Run Flow in the supplied practice. January has three rows, February two, March two. Expect seven rows and four columns. January’s repeated order 1002 remains twice."),
            .init(title:"Inspect alignment",text:"February’s fields have a different order. By name still puts customer and amount in the correct columns. March lacks notes, so its notes are missing. Select Union and compare Column alignment with Results → Output."),
            .init(title:"Change coverage",text:"Choose Shared columns only, Apply and run: notes disappears, but all seven rows remain. Require identical names stops because March lacks notes. Restore Include all."),
            .init(title:"Order and origins",text:"Enable Add input identifier, name it source_input, Apply and run. Move Table 3 earlier with its grip or arrows, Apply and run again: March’s rows come first while its identifier remains table3. Source connections do not change."),
            .init(title:"Position and types",text:"By position ignores names. This supplied example should stop on the incompatible types caused by February’s changed order. Revert or restore By name. Checked numeric widening permits only exactly representable integer/number combinations; it cannot fix text-versus-number alignment. Use Columns when an explicit conversion is intended.")
        ],reflection:"Why does Union keep repeated order 1002? Why can sorting the inputs change rows without changing identifiers? What could go wrong if position matching silently converted text to numbers? This practice is editable and unscored; opening it does not award mastery."),
        "summarize":.init(introduction:"An order can have several item lines. To report a total per order, those lines must become one summary row rather than one prediction per line.\n\nFollow the supplied canvas:\n- [Eight order lines](kwip-node://data/observations) reads synthetic order_id, amount and item values.\n- [One row per order](kwip-node://data/summary) groups those lines and calculates a count, a total and joined item text.\n- [Explore order summaries](kwip-node://data/view) displays the four resulting order summaries.\n\nJoin text puts several item names in one cell. Its separator can be a real newline; this is text joining, not numeric addition.",sections:[
            .init(title:"Predict, then run",text:"Run Flow. Eight synthetic order lines become four summaries. Order A has three lines totaling 43.5 and items Notebook, Pen, Notebook."),
            .init(title:"Inspect the grids",text:"Select Summarize. Group by order_id and inspect Count rows, Sum of amount and Join text of item. Results → Output exposes the captured table. Double-click an overflowing items cell to open its read-only text above the table. This example fits on one text page. Longer values use Previous/Next text page; Copy page copies only the displayed page. Close the detail area when finished."),
            .init(title:"Change text joining",text:"Select the Join text row. Newline is a real line break. Change Separator to Comma + space, enable Remove duplicate text, Apply and run. Order A becomes Notebook, Pen. With Newline restored, the unique items appear on separate lines. Incoming row order determines text order; group identities still record exact membership. For a separate exact-decimal workflow, keep source values as Text and choose Sum exact decimal text. Ordinary Number Sum is unchanged; do not switch these supplied integer amounts just to try the new operation."),
            .init(title:"Handle missing values",text:"Order C has one missing item: Skip gives Sticker; Return missing gives a missing items value; Stop run produces an attributed diagnostic. Restore Skip. Empty text is a separate choice, and Skip empty text does not trim whitespace."),
            .init(title:"Edit and compare",text:"Add a Mean of amount, name it average_amount and Apply. Rename/reorder summaries with grips or arrows; use Find summary to navigate. Revert discards the whole draft. Remove order_id from Group by to produce one global summary, then restore the original grouping. Existing Aggregate rows examples remain valid.")
        ],reflection:"Why does Count rows include Order C’s missing item? Why must Join text refuse a numeric column? What changes when duplicate text is removed? This editable practice has no scored completion or mastery award."),
        "sort":.init(introduction:"Suppose support requests need to be handled customer by customer, with higher-priority requests first within each customer. A second key resolves the order only when the first key ties.\n\nThe supplied canvas is Table Input → Sort → View. It contains six requests, identified S1 through S6, with customer, priority and region fields. One customer and one priority are missing. Sort changes the table passed downstream; clicking a Results column header only changes your view of it.\n\nThe saved keys compare customer names without case differences, then priority in descending order. You will check ties and missing placement separately.",sections:[
            .init(title:"Run the saved ordering",text:"Run Flow and inspect Sort → Results → Output. The customer key uses casefold, ascending, missing last. Priority is descending, missing first. Expected request order: **S5, S2, S3, S6, S1, S4**."),
            .init(title:"Explain the tie",text:"S2 and S3 have equal keys; S2 remains first. Reverse customer direction: the equal pair still retains its order."),
            .init(title:"Separate null placement",text:"Put missing customer first, then reverse direction. S4 stays first."),
            .init(title:"Compare text",text:"Choose Exact for customer and inspect the changed case ordering. Reorder keys using arrows or grips. Confirm all six request identities remain.")
        ],reflection:"Which key breaks each tie? Why does changing descending direction leave missing placement unchanged? Why cannot viewer sorting prove the downstream table is sorted? This editable practice is unscored and does not award mastery."),
        "unique":.init(introduction:"Repeated customer observations can be useful evidence rather than mistakes to delete silently. Unique lets you retain one representative and inspect the remaining records separately.\n\nThe supplied canvas reads seven requests, U1 through U7. Unique groups rows by customer **and** region; each output connects to its own View. Casefold comparison treats Straße, STRASSE and straße as the same customer. It does not rewrite their text.\n\nPredict which row First will keep in each group. Duplicates means the other members of those groups, not a second copy of every retained row.",sections:[
            .init(title:"Inspect both branches",text:"Run Flow and open both View tables. Compound customer/region keys use casefold, First and Equal missing. Unique requests are **U1, U4, U6, U7**; Duplicates are **U2, U3, U5**. U7 has the same customer as U1 but a different region."),
            .init(title:"Retain Last",text:"Unique becomes **U3, U5, U6, U7**, still in source order."),
            .init(title:"Missing policies",text:"Distinct rows keeps both U4 and U5. Stop run refuses their missing customer."),
            .init(title:"Case and coverage",text:"Exact comparison separates the three case variants. For every successful run, verify that counts add to seven and no request appears in both outputs. Select only request as key: all seven are Unique and Duplicates is empty.")
        ],reflection:"Why does Last still preserve source order? What happens to a row with just one missing compound-key field? Does running on a sample establish global uniqueness? This editable practice is unscored and does not award mastery."),
        "reshapeTable":.init(introduction:"Monthly sales can be stored with one column per month or with one row per customer/month. The useful layout depends on what the next tool expects.\n\nThe supplied Long canvas is Table Input → Reshape Table → View. Ada and Ben each have January and February fields. Long keeps customer as the identifier and emits a separate row for each selected month. A missing February value is still an observation unless you explicitly drop it.\n\nThe separate Wide practice is available in Exercise choices & reference. Open it only when you reach the Wide steps; it replaces the active example, so save your Long work first.",sections:[
            .init(title:"Long: one row per month",text:"Run Flow in the supplied Long canvas. Ada has January 10 and February 12; Ben has January 20 and missing February. Expect four rows: Ada/jan/10, Ada/feb/12, Ben/jan/20, Ben/feb/missing."),
            .init(title:"Change order",text:"Select Reshape Table. Move feb above jan in Value columns, Apply and run. Expect Ada/feb before Ada/jan, and Ben/feb before Ben/jan. The source rows stay in order."),
            .init(title:"Drop one missing observation",text:"Choose Drop emitted row. Expect three rows; only Ben/feb disappears. Restore Keep. Rename field-name output to month and value output to sales, Apply and inspect Results."),
            .init(title:"Catch a mistake",text:"Also choose customer as a value field while it remains an identifier. Apply should refuse overlapping selections. Revert. Mixing text and integer values also requires an explicit conversion; widening is only for exactly representable numeric mixtures."),
            .init(title:"Wide: one column per month",text:"Save your Long work. In Exercise choices & reference, choose Open Wide practice, then run it. Expect customer, sales_feb, sales_jan, units_feb, units_jan. Ada is 12/10/2/1; Ben is missing/30/missing/3. Two value rows each contribute one field per observed month."),
            .init(title:"Choose missing combinations",text:"Choose Fixed fill, Integer, 0. Apply and run: Ben’s February fields become zero. Existing missing observations would still follow the reducer’s policy. Restore Missing."),
            .init(title:"Try prefixes and limits",text:"Set both prefixes to the same value. Apply/run refuses the resulting column-name collision. Revert. Set Maximum output columns to 4: the five-column output is refused. Restore 128."),
            .init(title:"Duplicate policy",text:"To explore duplicates, edit a copy of the practice CSV by adding Ada,jan,20,2 and reconnect it through Table Input. Stop run refuses the pair. Choose Aggregate: sales_jan becomes 30 and units_jan becomes 2. First/Last are explicit alternatives that follow incoming order. Never silently choose a duplicate to make a pivot succeed.")
        ],reflection:"Why does dropping a missing Long value remove only one row? Why does Wide need an explicit duplicate policy? How could a working sample miss a possible month? Why should repeated customers stay together when evaluating a model? These practices are editable and unscored; opening them does not award mastery."),
        "table-output":.init(introduction:"After preparing a table, you may need a file that another application can read. Table Output writes the selected complete upstream table to a folder you choose.\n\nThe supplied Table Input → Table Output canvas contains twelve synthetic orders. Each has order_id, quantity, price and notes. Notes deliberately include punctuation, accented text and a line break so you can check the saved format.\n\nThe practice has no permission to write to a destination yet. You must choose the folder explicitly. Its saved receipt records the write that actually happened; opening the lesson or History does not write a file.",sections:[
            .init(title:"Choose a folder",text:"Select Table Output, choose a local folder and keep prepared-orders.csv. The practice contains no destination permission. Run Flow."),
            .init(title:"Verify complete output",text:"Read the saved receipt and open the file. Expect twelve data rows, a header, ordered columns order_id, quantity, price, notes and final order A12. Check embedded commas, a quoted value, café and a note spanning two lines."),
            .init(title:"Protect existing files",text:"Run again. Stop must preserve the first file. Choose a new filename, or explicitly select Replace file atomically."),
            .init(title:"Compare formats",text:"Choose a new filename and TSV, Parquet, JSON records, JSON rows plus schema, NDJSON or Excel. Apply before running each. Parquet retains types; JSON records uses names as keys; rows plus schema includes ordered type metadata; NDJSON has one compact object per line. Excel creates a whole new workbook, and =2+3 remains literal text."),
            .init(title:"Inspect options",text:"Try UTF-8 BOM and CRLF, a custom separator, explicit missing text and custom numeric .2f. Custom formatting changes values deliberately. In Parquet compare compression and row-group sizes. In Excel try start C3, header, freeze and autofilter; precision policy stops or writes exact text when Excel cannot preserve a value."),
            .init(title:"Try a database destination",text:"1. Select Table Input and Refresh preview so the mapping grid has known source names and types. Then select Table Output and change Destination to Database. Expand Exercise choices & reference and use Copy disposable SQLite practice database to create a new copy in a folder you choose. Choose that file in Table Output, then grant its containing folder for transaction journals. Use a test copy: Run Flow writes to the chosen database.\n2. Choose Create table and name it practice_orders. Test connection reads its metadata without writing.\n3. Include order_id, quantity, price and notes in the mapping grid. Keep their source names visible, rename quantity to item_count and choose order_id as the primary key. Reorder a selected row with the arrows; exclusion changes the columns written. Apply, then Run Flow.\n4. Inspect Write receipt and Input table. Committed confirms acknowledgment of this transaction; it does not claim separate inserted/updated counts.\n5. Test connection again, choose Upsert and the existing primary key. Map quantity to the known item_count destination. Apply and run: the same keys update rather than duplicate the twelve orders. Create again must refuse the existing table.\n\nFor PostgreSQL/MySQL, use your own disposable destination and a private connection profile with Table Output writes explicitly enabled. Do not put passwords in lessons or graph settings. A connection test never writes. MySQL requires InnoDB and exactly one unique key for Upsert. An unknown outcome requires checking the database and acknowledging the receipt before another write."),
            .init(title:"Send a table to an API",text:"Use a disposable endpoint you control: this step sends real requests when Run Flow is pressed. Select [Save complete orders](kwip-node://data/table-output), choose Destination API, enter its HTTPS URL and request method, then save a private connection with Table Output requests enabled. Keep credentials out of query/header text. Choose one request per row or a supported batch array, then use Auto-map by name and the column grid to rename JSON fields, choose scalar types and order the mapping. Apply saves settings; Run Flow sends the complete prepared table. Inspect Delivery receipt and Input table. HTTP 202 means accepted, not that the service finished processing. A lost response or partial delivery requires checking the endpoint and acknowledging the receipt before a new run; earlier requests cannot be rolled back. Restore File or Database when finished. Opening this lesson or History never sends a request."),
            .init(title:"Read a JSON API",text:"On a separate copy of the practice, select [Twelve synthetic orders](kwip-node://data/source), choose API, and enter an HTTPS GET endpoint you control. Add its nonsecret query parameters and a private authentication profile. Set the Records path to the JSON array, for example /data/orders. Add one mapping per desired column: a JSON Pointer source path, a readable column name and its type. Choose pagination only when required by the endpoint; cursor and next-link fields are response paths. Apply, then Fetch snapshot & inspect response. Confirm values in Results before running the flow. Run Flow fetches a new immutable snapshot. Page/byte/row/time limits cause failure instead of quietly truncating a complete table. History reads captured data. The supplied CSV canvas remains usable without API credentials or a network connection."),
            .init(title:"Schedule a saved workflow",text:"Use a disposable destination for this optional step. Save the canvas, then open Configure → Scheduled runs. Add a rule for this project and choose its saved canvas version. Unsaved edits will not change that rule.\n\nChoose a future one-time run and your time zone. Keep Skip occurrence and Skip missed runs while learning. Expand Access & output destinations, review the writes and allow unattended use only for your test destination. Apply the rule; workspace scheduling must also be enabled. Run now tests the saved version once without enabling recurrence.\n\nOpen Job history to inspect its status, captured outputs and write receipts. Optional run-detail capture uses the project's existing controls; required model and delivery evidence remain. An uncertain write pauses the rule until you check the destination and acknowledge the outcome. Global Settings → Scheduled runs shows these same rules across projects. Pause all when finished. Scheduled runs require \(ProductBrand.name) open and the Mac awake; opening this lesson or History never starts one."),
            .init(title:"Receive a local webhook",text:"A webhook starts a saved workflow when another program on this Mac sends it an authenticated request. It is not a public Internet URL. \(ProductBrand.name) must be open and the Mac awake.\n\n1. Save a disposable copy of your workflow, then open Configure → Webhooks. Add an endpoint and choose the saved canvas version. Keep Trigger only to use the workflow’s existing sources. To supply event rows, first configure a Table Input for JSON document and save again; choose JSON records into a table, that input, a records path such as items, and the fields and types to keep. Preview a synthetic payload before applying.\n2. Keep signed requests unless your local client needs a Bearer token. Apply, then use Show secret privately and Copy client example to configure your sender. Never put the secret in a canvas, screenshot or source file. Authorize output writes only to your disposable test destination. Enable this endpoint and the local listener.\n3. Inspect Delivery history. Accepted means durably queued; Completed means the workflow finished. Reuse the same delivery ID and identical body only for an exact retry. A duplicate refers to the original delivery and does not run again while that receipt is retained. Invalid fields/types are refused. Queued requests wait for shared run admission.\n\nOpen a job to inspect its captured outputs without sending the event again. An uncertain write pauses the endpoint for review. Global Settings → Webhooks shows the same endpoints, port, limits and deliveries across projects. Pause the listener when finished; pending requests stay recorded, and an active job continues until cancelled."),
            .init(title:"Review saved authority",text:"Change configuration after a run. An older receipt describes that captured write. Opening History does not save again. New portable replay requires an explicit local destination binding.")
        ],reflection:"Why does a table preview not limit the export? Why is quoting alone insufficient to prevent spreadsheet interpretation? Why does copied-image output need captured bytes, relative references and a manifest? This practice is editable and unscored; opening it does not award mastery."),
        "text-encoding":.init(introduction:"A model cannot use letters as numeric indices until a tokenizer assigns each token an integer ID. An ID identifies a vocabulary entry; it is not a meaning, a probability or an embedding vector.\n\nThe supplied canvas is:\n- [Four short texts](kwip-node://data/observations): To be, or not, To be or not, and To be?. The label column passes through unchanged.\n- [Encode characters](kwip-node://data/text): assigns one token per Unicode code point, including spaces, using a supplied vocabulary.\n- [Explore tokens](kwip-node://data/view): displays the resulting table.\n\nUnknown ID 0 represents a token outside that vocabulary; padding ID 1 is reserved for later length handling. The question mark is deliberately unsupported. This first canvas does not train a model.",sections:[
            .init(title:"Inspect IDs and vocabulary",text:"Run the four short texts. Select Text encoding and inspect its Output and Vocabulary tables. The supplied vocabulary reserves unknown ID0 and padding ID1; T is2, o is3, space is4, b is5 and e is6. To be therefore becomes [2,3,4,5,6]."),
            .init(title:"Compare letter case",text:"1. Select Encode characters and change letter case to Lowercase.\n2. Apply and run again.\n3. Inspect the first token in To be: uppercase T has ID 2, while lowercase t is separately present in the supplied vocabulary with ID 10. The source text remains inspectable.\n\nNormalization changes what gets tokenized. It does not silently extend a supplied vocabulary."),
            .init(title:"Refuse an unknown token",text:"Change Unknown token to Refuse. Apply and run; the unsupported character in the last record produces an attributed diagnostic. Restore Use <unk>."),
            .init(title:"Reserve boundary tokens",text:"Add beginning/end tokens, rerun, and inspect their reserved IDs. Padding is only reserved here; actual padding belongs to Train’s explicit length policy."),
            .init(title:"Use the vocabulary in training",text:"Open token-sequence classifier from Exercise choices & reference when you want the separate training example. Save the current canvas first.\n\nFit on Training learns vocabulary only from Training and applies the same saved mapping to Validation/Test. Train maps each token column to a declared named integer model input. The IDs, vocabulary size, padding ID and expected sequence length must agree. Numeric inputs can accompany tokens when they describe the same observations.\n\nText encoding chooses IDs. Sequence windows creates shifted targets; the next-token training and Generate text lessons build on that boundary. File Input reads images and PCM WAV recordings. Prepare media supplies explicit tensors; Extract text, Transcribe audio and Classify audio use their own verified model/processor paths.")
        ],reflection:"Predict one change, run it, then compare the actual captured table with your prediction. This is an editable, unscored practice; reading and running do not award an assessment pass."),
        "sequence-windows":.init(introduction:"Next-token training asks a model to predict the token immediately after each input position. Sequence windows turns a longer token sequence into aligned input/target examples.\n\nThe supplied canvas reads four text fragments belonging to two documents, soliloquy and reply. Columns makes fragment order an integer. Text encoding assigns character IDs, Next-token examples builds windows, and Explore aligned pairs shows their contents.\n\nWith context length 8, each input has eight positions. It needs nine real source tokens to form eight shifted targets. An input beginning T, o pairs with targets beginning o, space. These are examples for training, not generated predictions.",sections:[
            .init(title:"Inspect the shift",text:"Run the practice and select Next-token examples. Inspect input_ids or target_ids in Output. Position 0 pairs T with o in the fragment beginning To be. Context 8 needs 9 real source tokens. Back to Output returns to the table."),
            .init(title:"Change window overlap",text:"Change Stride to 4, Apply and rerun. Windows overlap within a document, so there are more examples. Their start offsets remain inspectable. Stride controls starts; it does not change the next-token shift."),
            .init(title:"Keep a partial tail",text:"Change Incomplete window to Pad. Keep the supplied vocabulary’s padding ID 1. Inspect a short final window: Loss excludes padded positions and valid_length counts real targets. No window with zero valid targets is emitted."),
            .init(title:"Respect document order",text:"Choose Ordered rows in each document, Document column document, Order column fragment, Ascending. Apply and rerun. Fragment 2 precedes 10 numerically, even though the file lists 10 first. Tokens join only within the same document, with no added separator. Change Direction to verify the explicit order."),
            .init(title:"Protect the evaluation boundary",text:"Split independent documents or contiguous corpus regions before fitting a vocabulary and creating overlapping windows. Otherwise nearly identical windows could land on both sides of the evaluation split. A whole book stored as one row needs explicit source regions/fragments first.\n\nSequence windows keeps each partition separate. It does not create an attention mask: a model that mixes positions must explicitly enforce causality."),
            .init(title:"Try the separate training example",text:"Save this canvas, then use Open next-token training practice in Exercise choices & reference. Run it and inspect Train’s predictions table.\n\nValidation cross entropy measures prediction error per valid token; perplexity is its exponential. Padded targets contribute neither loss nor gradient. The tiny embedding + linear model learns pointwise token transitions; it is not the stacked attention architecture of Llama. Generate text can continue a prompt using a compatible completed next-token model and its saved tokenizer.\n\nKeep the model’s context, output class count and vocabulary aligned. Inspect the actual validation evidence instead of assuming this tiny model will generate useful prose.")
        ],reflection:"Predict one change, run it, then compare the actual captured table with your prediction. This is an editable, unscored practice; reading and running do not award an assessment pass."),
    ]
    static func steps(_ id:String)->[LessonContentStep]? {
        guard let packet=packets[id] else {return nil}
        return [LessonContent.step("goal","Meet the supplied canvas",packet.introduction)] + packet.sections.enumerated().map { index,section in
            LessonContent.step(index==0 ? "build":"build.\(index)",section.title,section.text,kind:.canvasAction)
        } + [LessonContent.step("inspect","Check your understanding",packet.reflection,kind:.question)]
    }
}
